{
  "core_question": "How should a company launch a digital therapeutic for insomnia in the US and Germany, including regulatory pathways, reimbursement strategy, clinician adoption, pricing, and revenue projections over three years?",
  "rationale": "The question spans clinical regulation (FDA/G-BA), legal reimbursement frameworks (CMS/Medicaid and German G-BA), and financial planning (budget, runway, pricing, revenue modeling).",
  "routes": ["healthcare", "legal", "finance"],
  "sub_questions": {
    "healthcare": "What is the appropriate FDA regulatory pathway (e.g., 510(k), De Novo, PMA) for a digital therapeutic intended to treat insomnia in adults, including key data requirements and expected timeline?",
    "legal": "Given recent changes to US Medicare/Medicaid coverage policies for digital therapeutics and German G-BA reimbursement guidelines, what are the current legal requirements and potential hurdles for obtaining reimbursement in each country, and how might enforcement uncertainty affect the launch strategy?",
    "finance": "Based on a $6.2M budget and 24 months of runway, propose a three-year revenue projection model that incorporates realistic per-patient pricing assumptions, clinician adoption rates, and market penetration targets for both US and Germany."
  },
  "requires_recency_disclosure": true,
  "recency_notes": "Recent FDA digital therapeutic guidance updates (post-2023), CMS coverage determination changes in 2024, and German G-BA reimbursement criteria revisions in 2023/24 may affect regulatory and reimbursement timelines."
}
